/**
 * Bundled tech-tree topologies, generated by `scripts/extract/build_techtree.py`.
 *
 * Two realm variants ship (the ships view's WG/Lesta switch picks one):
 *   - `tech_tree.json`   — the WG-cluster tree (wowsinfo bridge), the
 *     branch-structure reference; includes premium/special side leaves.
 *   - `tech_tree_lesta.json` — the Lesta tree, read straight from the
 *     game client's GameParams research graph (research lines only).
 *
 * Each node is keyed by shipId and carries the minimum the renderer needs:
 * tier, type, nation, rarity, archetype (branch flavour), and the shipIds it
 * unlocks. Premium/special ships that hang off a tech-tree node as a side
 * leaf are included with isPremium/isSpecial set (WG tree only).
 */
import treeWgRaw from "@/data/tech_tree.json";
import treeLestaRaw from "@/data/tech_tree_lesta.json";
import branchFeaturesRaw from "@/data/tech_tree_branch_features.json";
import { i18n, type Locale } from "@/i18n";

export type TechTreeRealm = "wg" | "lesta";

export interface TechTreeNode {
  shipId: number;
  index: string;
  name: string;
  tier: number;
  type: string;
  nation: string;
  isPremium: boolean;
  isSpecial: boolean;
  rarity: string;
  archetype: string;
  nextShips: number[];
  group: string;
}

const TREES: Record<TechTreeRealm, Record<string, TechTreeNode>> = {
  wg: treeWgRaw as Record<string, TechTreeNode>,
  lesta: treeLestaRaw as Record<string, TechTreeNode>,
};

/** All tech-tree nodes of a realm, keyed by stringified shipId. */
export function allTechTreeNodes(realm: TechTreeRealm = "wg"): Record<string, TechTreeNode> {
  return TREES[realm];
}

/** One node by shipId in a realm, or null. */
export function techTreeNode(shipId: number, realm: TechTreeRealm = "wg"): TechTreeNode | null {
  return TREES[realm][String(shipId)] ?? null;
}

/** The researchable WG-tree ships the Lesta tree carries no node for — the
 *  branches only WG ever grew (the Commonwealth cruisers, the Pan-America
 *  battleships, the Pan-Europe battleships, …). The two realms' trees also
 *  hold ships only Lesta grew; that direction ships as the overlay data
 *  file (ships_lesta.json) instead.
 *
 *  This set is the DEGRADED fallback for hiding WG-only ships from the
 *  Lesta-mode encyclopedia list: the authoritative filter is the full-dump
 *  roster diff (ships_wg_only.json via shipsLesta.ts), which also covers
 *  the WG-only premiums and keeps hulls Lesta carries in non-tree groups
 *  (the Piemonte ultimate) listed. Premium/special side leaves are exempt
 *  here for the same reason — their Lesta availability is unknowable from
 *  tree data alone. */
export const WG_EXCLUSIVE_TREE_SHIP_IDS: ReadonlySet<number> = new Set(
  Object.values(TREES.wg)
    .filter((n) => !n.isPremium && !n.isSpecial && !(String(n.shipId) in TREES.lesta))
    .map((n) => n.shipId),
);

/**
 * Aliases resolving to the tree files' nation keys. WG's encyclopedia API
 * says "europe" while the game files say "pan_europe"; ship_names.json keeps
 * the raw game-file spellings "united_kingdom" and "russia". The WG API codes
 * uk/ussr are already the stored keys.
 */
const NATION_ALIASES: Record<string, string> = {
  europe: "pan_europe",
  united_kingdom: "uk",
  russia: "ussr",
};

/** Every node belonging to a nation in a realm. */
export function nationNodes(nation: string, realm: TechTreeRealm = "wg"): TechTreeNode[] {
  const key = NATION_ALIASES[nation] ?? nation;
  return Object.values(TREES[realm]).filter((n) => n.nation === key);
}

/**
 * Group a nation's nodes by ship type, each as a list of chains. A chain is a
 * root-to-leaf path through `nextShips` (a single branch). Forks (a node with
 * ≥2 children) spawn parallel chains so each sub-branch renders as its own
 * row of tiers. Side leaves (premium/special ships attached to a tree node)
 * are returned alongside the chain they hang off.
 */
export interface TechTreeBranch {
  /** shipIds along this branch, tier-ascending. */
  ships: number[];
  /** archetype code of the highest-tier ship in the branch (for labelling). */
  archetype: string;
}
export interface NationTree {
  type: string;
  branches: TechTreeBranch[];
}

export function nationTree(nation: string, realm: TechTreeRealm = "wg"): NationTree[] {
  const nodes = nationNodes(nation, realm);
  const byType: Record<string, TechTreeNode[]> = {};
  for (const n of nodes) (byType[n.type] ??= []).push(n);

  const out: NationTree[] = [];
  for (const [type, list] of Object.entries(byType)) {
    const byId = new Map(list.map((n) => [n.shipId, n]));
    // Roots: nodes nobody points to within this nation+type (tier-1 starters,
    // plus any orphans). A child is "pointed to" if some node lists it in
    // nextShips.
    const pointedTo = new Set<number>();
    for (const n of list) for (const nx of n.nextShips) if (byId.has(nx)) pointedTo.add(nx);
    const roots = list.filter((n) => !pointedTo.has(n.shipId)).sort((a, b) => a.tier - b.tier);

    const branches: TechTreeBranch[] = [];
    const walk = (node: TechTreeNode, path: number[]): void => {
      // Depth-first in nextShips order, so fork columns keep the game's own
      // line order (the LIFO stack this once used emitted them reversed —
      // the leftmost fork column was the last-listed line). Cross-type
      // children are simply absent from byId here: they root their own
      // column in their own type section, and nationCrossLinks hands the
      // edge to the renderer for the across-section connector.
      const kids = node.nextShips.map((id) => byId.get(id)).filter((n): n is TechTreeNode => !!n);
      if (kids.length === 0) {
        branches.push({ ships: path, archetype: node.archetype });
        return;
      }
      for (const k of kids) walk(k, [...path, k.shipId]);
    };
    for (const r of roots) walk(r, [r.shipId]);
    out.push({ type, branches });
  }
  // Stable type order: Battleship, Cruiser, Destroyer, Submarine,
  // AirCarrier — carriers sit farthest right because their cross-type
  // research edges leave the destroyer section high (tier IV), sailing
  // over the submarine section's EMPTY upper rows (sub lines start at
  // tier VI); submarines sit next to destroyers because their cross-type
  // edges leave at tier VI. Both orderings (this and the pre-swap
  // DD|CV|SS) avoid edge occlusion for DD→CV/DD→SS, but this one also
  // keeps every DD→SS hand-off adjacency, matching the in-game layout.
  const TYPE_ORDER = ["Battleship", "Cruiser", "Destroyer", "Submarine", "AirCarrier"];
  out.sort((a, b) => TYPE_ORDER.indexOf(a.type) - TYPE_ORDER.indexOf(b.type));
  return out;
}

/**
 * The tree ships a node unlocks: nextShips minus the premium/special side
 * leaves (those render as attached leaves, never as research continuations).
 * This is the "does this ship fork" / "which links are research links" test
 * the renderer and the link-info tooltips share.
 */
export function treeNextShipIds(node: TechTreeNode, realm: TechTreeRealm = "wg"): number[] {
  return node.nextShips.filter((id) => {
    const child = TREES[realm][String(id)];
    return !!child && !child.isPremium && !child.isSpecial;
  });
}

/** A research edge whose two ends are different ship types (e.g. the IJN
 *  cruiser 筑摩 unlocking the destroyer 海风). The tree groups nodes by type,
 *  so these edges never surface inside `nationTree`'s branches — the renderer
 *  draws them as connectors across the type sections instead. */
export interface TechTreeCrossLink {
  /** shipId of the unlocking (parent) ship. */
  from: number;
  /** shipId of the unlocked (child) ship, in its own type section. */
  to: number;
}

/** Every cross-type research edge within a nation, both ends researchable. */
export function nationCrossLinks(nation: string, realm: TechTreeRealm = "wg"): TechTreeCrossLink[] {
  const key = NATION_ALIASES[nation] ?? nation;
  const out: TechTreeCrossLink[] = [];
  for (const n of Object.values(TREES[realm])) {
    if (n.nation !== key || n.isPremium || n.isSpecial) continue;
    for (const id of treeNextShipIds(n, realm)) {
      const child = TREES[realm][String(id)];
      if (child.nation === key && child.type !== n.type) {
        out.push({ from: n.shipId, to: child.shipId });
      }
    }
  }
  return out;
}

// ── Branch features — the in-game link ⓘ "warship characteristics" ──────
// Generated by `scripts/extract/build_branch_features.py` out of the game
// client's encrypted BranchesSettings module: per-branch feature groups
// (the popup the in-game tree shows when hovering the ⓘ above a branch's
// first ship) plus the shipId → branch mapping that marks segment starts.

export interface TechTreeBranchInfo {
  /** Feature icon keys shown on the branch's cards in-game (MAIN_ and CLASS_). */
  card: string[];
  /** Feature groups: (category code, ordered FEAT_ keys). */
  groups: [string, string[]][];
}

interface FeatureTextMap {
  [key: string]: Record<string, string>;
}

interface BranchFeaturesData {
  branches: Record<string, TechTreeBranchInfo>;
  shipBranch: Record<string, string>;
  texts: {
    title: Record<string, string>;
    note: Record<string, string>;
    category: FeatureTextMap;
    feat: FeatureTextMap;
  };
  icons?: {
    card: Record<string, string>;
    category: Record<string, string>;
  };
}

const featureData = branchFeaturesRaw as unknown as BranchFeaturesData;

/** Generic per-type branches used when a line has no specific record. */
const TYPE_GENERIC_BRANCH: Record<string, string> = {
  Battleship: "BATTLESHIPS",
  Cruiser: "CRUISERS",
  Destroyer: "DESTROYERS",
  AirCarrier: "AIR_CARRIERS",
  Submarine: "SUBMARINES",
};

/** The game branch (BranchesSettings enum name) a tree ship's segment sits
 *  in — segment starts are where this changes along a research line. Built
 *  from the WG tree; Lesta-only ships resolve to "" (no segment ⓘ there). */
export function techTreeShipBranch(shipId: number): string {
  return featureData.shipBranch[String(shipId)] ?? "";
}

/** One branch's feature record; lines without their own record fall back to
 *  the type-generic set (exactly the chain the in-game system walks). */
export function techTreeBranchInfo(
  branchName: string,
  type?: string,
): TechTreeBranchInfo | null {
  const specific = featureData.branches[branchName];
  if (specific) return specific;
  const generic = type ? featureData.branches[TYPE_GENERIC_BRANCH[type] ?? ""] : undefined;
  return generic ?? null;
}

/** Whether a branch carries actual feature rows — several game branches
 *  (shared trunks like US_CA_EARLY, the type-generic sets) ship card icons
 *  only, and an empty characteristics popup is not worth a ⓘ. */
export function techTreeBranchHasContent(branchName: string, type?: string): boolean {
  return (techTreeBranchInfo(branchName, type)?.groups.length ?? 0) > 0;
}

/** The bundled feature texts are game content straight from the client's
 *  localization (official zh-Hans + ru-RU where the Lesta client carries
 *  it, curated en-US), not UI chrome — resolve them against the active
 *  locale here, falling back to en-US. */
function featureText(map: Record<string, string> | undefined): string {
  if (!map) return "";
  const locale = (i18n.global.locale as unknown as { value: Locale }).value;
  const tag = locale.startsWith("zh")
    ? "zh-Hans"
    : locale.startsWith("ru")
      ? "ru-RU"
      : "en-US";
  return map[tag] ?? map["en-US"] ?? "";
}

/** Localized popup title for the branch-feature ⓘ card. */
export function techTreeFeatureTitle(): string {
  return featureText(featureData.texts.title);
}

/** Localized comparison-basis footnote for the branch-feature ⓘ card. */
export function techTreeFeatureNote(): string {
  return featureText(featureData.texts.note);
}

/** One localized feature sentence, "＋"/"−"-marked by its FEAT quality. */
export function techTreeFeatText(featKey: string): string {
  const text = featureText(featureData.texts.feat[featKey]);
  if (!text) return "";
  return (featKey.includes("_BAD_") ? "− " : "＋ ") + text;
}

/** Localized category label for a feature group. */
export function techTreeFeatureCategoryText(category: string): string {
  return featureText(featureData.texts.category[category]) || category;
}

/** Public URL of a bundled feature icon (small game-client PNGs served from
 *  the webui publicDir), or null when the key has no icon bundled. */
function featureIconUrl(file: string | undefined): string | null {
  return file ? `${import.meta.env.BASE_URL}images/tech-tree-features/${encodeURIComponent(file)}` : null;
}

/** Icon URL for a branch card-feature key (MAIN_/CLASS_), or null. */
export function techTreeCardIcon(key: string): string | null {
  return featureIconUrl(featureData.icons?.card[key]);
}

/** Icon URL for a feature-category code, or null. */
export function techTreeCategoryIcon(category: string): string | null {
  return featureIconUrl(featureData.icons?.category[category]);
}
